class BinaryIndexedTree():
    def __init__(self, n):
        self.size = n
        self.tree = [0]*n

    def sum(self, i):
        i, res = i + 1, 0
        while i > 0:
            res += self.tree[i - 1]
            i -= i & -i
        return res

    def add(self, i, x):
        i += 1
        while i <= self.size:
            self.tree[i - 1] += x
            i += i & -i

    def lower_bound(self, x):
        i, index = 1, 0
        while i*2 <= self.size:
            i *= 2
        while i > 0:
            if index + i - 1 < self.size and x > self.tree[index + i - 1]:
                x -= self.tree[index + i - 1]
                index += i
            i //= 2
        return index


