def main():
    # Read input
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Find starting position 'S'
    start_r, start_c = -1, -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start_r, start_c = i, j
                break
        if start_r != -1:
            break

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize component IDs and sizes
    component_id = [[0 for _ in range(W)] for _ in range(H)]
    component_sizes = [0]  # component 0 unused

    # BFS for the component containing 'S' (component 1)
    q = deque()
    q.append((start_r, start_c))
    component_id[start_r][start_c] = 1
    component_size = 1

    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if grid[nr][nc] in ('.', 'S') and component_id[nr][nc] == 0:
                    component_id[nr][nc] = 1
                    component_size += 1
                    q.append((nr, nc))

    component_sizes.append(component_size)

    # If all cells are reachable without breaking walls
    if component_size == H * W:
        print(component_size)
        return

    # BFS for other components
    current_id = 2
    for i in range(H):
        for j in range(W):
            if grid[i][j] in ('.', 'S') and component_id[i][j] == 0:
                q = deque()
                q.append((i, j))
                component_id[i][j] = current_id
                size = 1

                while q:
                    r, c = q.popleft()
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] in ('.', 'S') and component_id[nr][nc] == 0:
                                component_id[nr][nc] = current_id
                                size += 1
                                q.append((nr, nc))

                component_sizes.append(size)
                current_id += 1

    # Check walls adjacent to component 1
    max_reachable = component_sizes[1]
    last_seen = [0] * current_id
    wall_number = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                adjacent_to_C = False
                # Check if this wall is adjacent to component 1
                for dr, dc in directions:
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < H and 0 <= nj < W:
                        if component_id[ni][nj] == 1:
                            adjacent_to_C = True
                            break

                if adjacent_to_C:
                    wall_number += 1
                    sum_other = 0
                    # Check adjacent components
                    for dr, dc in directions:
                        ni, nj = i + dr, j + dc
                        if 0 <= ni < H and 0 <= nj < W:
                            cid = component_id[ni][nj]
                            if cid > 1 and last_seen[cid] != wall_number:
                                sum_other += component_sizes[cid]
                                last_seen[cid] = wall_number

                    # Total includes component 1, the wall cell, and connected components
                    total = component_sizes[1] + 1 + sum_other
                    if total > max_reachable:
                        max_reachable = total

    print(max_reachable)

