class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 0:
            return 0
        m = len(grid[0])
        if m == 0:
            return 0

        directions = [ (1, 1), (1, -1), (-1, 1), (-1, -1) ]
        dp = [ [ [ [0]*2 for _ in range(4)] for __ in range(m) ] for ___ in range(n) ]

        for dr_idx in range(4):
            dr, dc = directions[dr_idx]
            if dr == 1:
                row_order = range(n-1, -1, -1)
            else:
                row_order = range(n)
            if dc == 1:
                col_order = range(m-1, -1, -1)
            else:
                col_order = range(m)

            for x in row_order:
                for y in col_order:
                    for e_idx, e in enumerate([0, 2]):
                        if grid[x][y] != e:
                            dp[x][y][dr_idx][e_idx] = 0
                        else:
                            next_x = x + dr
                            next_y = y + dc
                            if 0 <= next_x < n and 0 <= next_y < m:
                                next_e = 0 if e == 2 else 2
                                next_e_idx = 0 if next_e == 0 else 1
                                dp[x][y][dr_idx][e_idx] = 1 + dp[next_x][next_y][dr_idx][next_e_idx]
                            else:
                                dp[x][y][dr_idx][e_idx] = 1

        max_len = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                current_max = 1
                for dr_idx in range(4):
                    dr, dc = directions[dr_idx]
                    next_i = i + dr
                    next_j = j + dc
                    if 0 <= next_i < n and 0 <= next_j < m:
                        len1 = 1 + dp[next_i][next_j][dr_idx][1]
                    else:
                        len1 = 1
                    current_max = max(current_max, len1)

                    for s in range(len1):
                        x = i + dr * s
                        y = j + dc * s
                        new_dr = dc
                        new_dc = -dr
                        new_x = x + new_dr
                        new_y = y + new_dc
                        if 0 <= new_x < n and 0 <= new_y < m:
                            k = s + 1
                            e = 2 if k % 2 == 1 else 0
                            if grid[new_x][new_y] != e:
                                continue
                            new_dr_idx = [1, 3, 0, 2][dr_idx]
                            e_idx = 1 if e == 2 else 0
                            len2 = dp[new_x][new_y][new_dr_idx][e_idx]
                            total = (s + 1) + len2
                            current_max = max(current_max, total)
                max_len = max(max_len, current_max)

        return max_len

